 "content": "from collections import Counter


def transform(grid):
    """Shift all foreground cells down by one row, clearing the vacated row."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out
